package com.alibaba.fastjson2;

import com.alibaba.fastjson2.reader.ObjectReader;
import com.alibaba.fastjson2.util.TypeUtils;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Type;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for the new {@link JSON#parseObject(String, Type, JSONReader.Context)} method.
 */
public class JSONParseObjectWithContextTest {

    @Test
    public void testParseObjectWithContext_NullInput() {
        JSONReader.Context context = JSONFactory.createReadContext();
        Type type = new TypeReference<List<String>>() {}.getType();

        assertNull(JSON.parseObject(null, type, context));
        assertNull(JSON.parseObject("", type, context));
    }

    @Test
    public void testParseObjectWithContext_SimpleGenericType() {
        JSONReader.Context context = JSONFactory.createReadContext();
        Type type = new TypeReference<List<String>>() {}.getType();

        List<String> result = JSON.parseObject("[\"hello\", \"world\"]", type, context);
        assertNotNull(result);
        assertEquals(2, result.size());
        assertEquals("hello", result.get(0));
        assertEquals("world", result.get(1));
    }

    @Test
    public void testParseObjectWithContext_MapGenericType() {
        JSONReader.Context context = JSONFactory.createReadContext();
        Type type = new TypeReference<Map<String, Integer>>() {}.getType();

        Map<String, Integer> result = JSON.parseObject("{\"a\": 1, \"b\": 2}", type, context);
        assertNotNull(result);
        assertEquals(2, result.size());
        assertEquals(1, result.get("a"));
        assertEquals(2, result.get("b"));
    }

    @Test
    public void testParseObjectWithContext_CustomContextFeatures() {
        JSONReader.Context context = JSONFactory.createReadContext();
        // Enable a feature to ensure context is used
        context.config(JSONReader.Feature.SupportAutoType, true);

        Type type = new TypeReference<List<String>>() {}.getType();
        List<String> result = JSON.parseObject("[\"test\"]", type, context);
        assertNotNull(result);
        assertEquals(1, result.size());
        assertEquals("test", result.get(0));
    }

    @Test
    public void testParseObjectWithContext_IgnoreCheckCloseFeature() {
        JSONReader.Context context = JSONFactory.createReadContext();
        // Enable IgnoreCheckClose to allow extra content
        context.config(JSONReader.Feature.IgnoreCheckClose, true);

        Type type = new TypeReference<List<String>>() {}.getType();
        // This should not throw even though there's extra content after valid JSON
        List<String> result = JSON.parseObject("[\"a\"] extra", type, context);
        assertNotNull(result);
        assertEquals(1, result.size());
        assertEquals("a", result.get(0));
    }

    @Test
    public void testParseObjectWithContext_InputNotEndException() {
        JSONReader.Context context = JSONFactory.createReadContext();
        // By default, IgnoreCheckClose is false
        Type type = new TypeReference<List<String>>() {}.getType();

        JSONException exception = assertThrows(JSONException.class, () -> {
            JSON.parseObject("[\"a\"] extra", type, context);
        });
        assertTrue(exception.getMessage().contains("input not end"));
    }

    @Test
    public void testParseObjectWithContext_ComplexNestedType() {
        JSONReader.Context context = JSONFactory.createReadContext();
        Type type = new TypeReference<Map<String, List<Map<String, Integer>>>>() {}.getType();

        String json = "{\"key1\": [{\"a\": 1}, {\"b\": 2}], \"key2\": []}";
        Map<String, List<Map<String, Integer>>> result = JSON.parseObject(json, type, context);

        assertNotNull(result);
        assertEquals(2, result.size());
        assertEquals(2, result.get("key1").size());
        assertEquals(1, result.get("key1").get(0).get("a"));
        assertEquals(2, result.get("key1").get(1).get("b"));
        assertTrue(result.get("key2").isEmpty());
    }

    @Test
    public void testParseObjectWithContext_WithTypeReference() {
        JSONReader.Context context = JSONFactory.createReadContext();

        // Using TypeReference directly
        TypeReference<List<String>> typeRef = new TypeReference<List<String>>() {};
        List<String> result = JSON.parseObject("[\"x\", \"y\"]", typeRef, context);

        assertNotNull(result);
        assertEquals(2, result.size());
        assertEquals("x", result.get(0));
        assertEquals("y", result.get(1));
    }

    @Test
    public void testParseObjectWithContext_EmptyJson() {
        JSONReader.Context context = JSONFactory.createReadContext();
        Type type = new TypeReference<List<String>>() {}.getType();

        // Empty JSON array
        List<String> result = JSON.parseObject("[]", type, context);
        assertNotNull(result);
        assertTrue(result.isEmpty());

        // Empty JSON object
        Type mapType = new TypeReference<Map<String, String>>() {}.getType();
        Map<String, String> mapResult = JSON.parseObject("{}", mapType, context);
        assertNotNull(mapResult);
        assertTrue(mapResult.isEmpty());
    }

    @Test
    public void testParseObjectWithContext_ConsistencyWithExistingMethod() {
        String json = "[\"a\", \"b\", \"c\"]";
        Type type = new TypeReference<List<String>>() {}.getType();

        // Using existing method
        List<String> existingResult = JSON.parseObject(json, type);

        // Using new method with default context
        JSONReader.Context context = JSONFactory.createReadContext();
        List<String> newResult = JSON.parseObject(json, type, context);

        assertEquals(existingResult, newResult);
    }
}
